import{_ as t,o as r,c as o,a5 as a}from"./chunks/framework.BmD0ICqc.js";const s="/study/images/browser/cors-origin-boundary.svg",c="/study/images/browser/cors-preflight.svg",k=JSON.parse('{"title":"同一オリジンポリシーとCORS — 送信と応答の公開","description":"","frontmatter":{"title":"同一オリジンポリシーとCORS — 送信と応答の公開","study":{"source":"新規執筆","section":"reference","format":"article","status":"published","domain":"browser","summary":"オリジンの境界、同一オリジンポリシー、CORSの応答検査を整理する。OPTIONSによるプリフライト、資格情報、no-corsで見える応答を区別する。","aliases":["オリジン","origin","同一オリジンポリシー","same-origin policy","SOP","same-site","opaque origin","CORS","Cross-Origin Resource Sharing","プリフライト","preflight","Access-Control-Allow-Origin","credentials","no-cors","opaque response","CSRF"],"verification":"一次資料照合（2026-11-05）"}},"headers":[],"relativePath":"browser/same-origin-cors.md","filePath":"browser/same-origin-cors.md"}'),i={name:"browser/same-origin-cors.md"};function h(d,e,n,l,p,g){return r(),o("div",null,[...e[0]||(e[0]=[a('<h1 id="同一オリジンポリシーとcors-—-送信と応答の公開" tabindex="-1">同一オリジンポリシーとCORS — 送信と応答の公開 <a class="header-anchor" href="#同一オリジンポリシーとcors-—-送信と応答の公開" aria-label="Permalink to &quot;同一オリジンポリシーとCORS — 送信と応答の公開&quot;">​</a></h1><p><strong>同一オリジンポリシー</strong>（Same-Origin Policy）は、あるページのコードが別のオリジンにある情報にアクセスできる範囲を制限します。<strong>CORS</strong>（Cross-Origin Resource Sharing）は、HTTPの応答を別のオリジンのコードに公開するための仕組みです。サーバーは公開条件を応答ヘッダーで示し、ブラウザがその条件を検査します。要求がサーバーに届くか、応答をJavaScriptから読めるかは別々に判断します。<a href="https://html.spec.whatwg.org/multipage/browsers.html#concept-origin" target="_blank" rel="noreferrer">WHATWG HTMLのOrigins</a>、<a href="https://fetch.spec.whatwg.org/#http-cors-protocol" target="_blank" rel="noreferrer">WHATWG FetchのCORS protocol</a></p><h2 id="オリジンを決める3つの要素" tabindex="-1">オリジンを決める3つの要素 <a class="header-anchor" href="#オリジンを決める3つの要素" aria-label="Permalink to &quot;オリジンを決める3つの要素&quot;">​</a></h2><p>HTTP(S)のオリジンは、<strong>スキーム・ホスト・ポート</strong>の組で決まります。ポートを省略したHTTPS URLは、既定の443番を明示したURLと同じオリジンです。パスやクエリが違っても、この3要素が一致すれば同一オリジンです。ローカル開発でも、同じホストの5173番と8000番を使うフロントエンドとAPIは別オリジンになります。<a href="https://html.spec.whatwg.org/multipage/browsers.html#concept-origin" target="_blank" rel="noreferrer">WHATWG HTMLのOrigins</a>、<a href="https://url.spec.whatwg.org/#concept-url-origin" target="_blank" rel="noreferrer">WHATWG URLのOrigin</a></p><table tabindex="0"><thead><tr><th>ページが <code>https://app.example.com/study/</code> の場合</th><th>同一オリジン</th><th>判定の理由</th></tr></thead><tbody><tr><td><code>https://app.example.com/assets/data.json</code></td><td>はい</td><td>パスだけが違う</td></tr><tr><td><code>https://app.example.com:443/</code></td><td>はい</td><td>443番はHTTPSの既定ポート</td></tr><tr><td><code>https://app.example.com:8443/</code></td><td>いいえ</td><td>ポートが違う</td></tr><tr><td><code>https://api.example.com/</code></td><td>いいえ</td><td>ホストが違う</td></tr><tr><td><code>http://app.example.com/</code></td><td>いいえ</td><td>スキームが違う</td></tr></tbody></table><p><strong>同一サイト</strong>（same-site）と同一オリジンでは、比較する項目が違います。たとえば <code>https://app.example.com</code> と <code>https://api.example.com</code> は、スキームと登録可能ドメインが同じなので同一サイトですが、別オリジンです。このため、Cookieの<code>SameSite</code>属性とCORSでは判定の単位が異なります。<a href="https://html.spec.whatwg.org/multipage/browsers.html#sites" target="_blank" rel="noreferrer">WHATWG HTMLのSites</a></p><p><code>iframe sandbox=&quot;allow-scripts&quot;</code> で読み込んだ文書には、同じホストのファイルを使っていても、ブラウザが個別の<strong>不透明なオリジン</strong>（opaque origin）を割り当てます。このオリジンがHTTPの<code>Origin</code>ヘッダーに現れるときの値は文字列の<code>null</code>です。別々の不透明なオリジンも同じ文字列に変換されるので、<code>null</code>だけでは発行元を識別できません。<a href="https://html.spec.whatwg.org/multipage/browsers.html#sandboxing" target="_blank" rel="noreferrer">WHATWG HTMLのSandboxing</a>、<a href="https://fetch.spec.whatwg.org/#origin-header" target="_blank" rel="noreferrer">WHATWG FetchのOriginヘッダー</a></p><figure class="study-figure"><img src="'+s+`" alt="スキーム、ホスト、ポートがそろうURLは同一オリジンになる。ホストやポートが変わると別オリジンになる。同じ配信元でも、サンドボックス内の文書は独自の不透明なオリジンを持つことを示す図" width="760" height="978" loading="lazy"><figcaption>パスだけが違うURLと、ホストやポートが違うURLを比べます。サンドボックス内では文書自身のオリジンも確認します。<a href="/study/images/browser/cors-origin-boundary.svg" target="_blank" rel="noopener">図を拡大する</a></figcaption></figure><h2 id="埋め込み、domへのアクセス、応答の読み取り" tabindex="-1">埋め込み、DOMへのアクセス、応答の読み取り <a class="header-anchor" href="#埋め込み、domへのアクセス、応答の読み取り" aria-label="Permalink to &quot;埋め込み、DOMへのアクセス、応答の読み取り&quot;">​</a></h2><p>画像の表示、別ページへの移動、フォームの送信など、別オリジンへ要求を送れる場面はあります。たとえば別オリジンのページを<code>iframe</code>に表示できても、親ページのスクリプトが子ページのDOMを直接読むことは制限されます。両方の文書が協力する場合は、<code>postMessage()</code>で決めた形式のデータを渡せます。受信側は<code>event.origin</code>とデータの形式を確認し、必要に応じて<code>event.source</code>で想定したウィンドウからの通知か確かめます。<a href="https://html.spec.whatwg.org/multipage/nav-history-apis.html#cross-origin-objects" target="_blank" rel="noreferrer">WHATWG HTMLのオリジン間でアクセス可能なプロパティ</a>、<a href="https://html.spec.whatwg.org/multipage/web-messaging.html#crossDocumentMessages" target="_blank" rel="noreferrer">WHATWG HTMLのCross-document messaging</a></p><p>HTTP応答を<code>fetch()</code>で読む場合、別オリジンへの通常の取得には<code>mode: &quot;cors&quot;</code>を使います。ブラウザが要求に<code>Origin</code>を付け、サーバーの<code>Access-Control-Allow-Origin</code>などを検査します。通過すると、ブラウザが公開できる部分を<code>Response</code>として渡します。これは取得した応答をスクリプトに公開する手続きなので、別オリジンのウィンドウや保存領域へアクセスできる範囲は変わりません。<a href="https://fetch.spec.whatwg.org/#cors-check" target="_blank" rel="noreferrer">WHATWG FetchのCORS check</a>、<a href="/study/browser/storage-lifetime.html">ブラウザの保存領域</a></p><h2 id="本要求の前にoptionsを送る条件" tabindex="-1">本要求の前にOPTIONSを送る条件 <a class="header-anchor" href="#本要求の前にoptionsを送る条件" aria-label="Permalink to &quot;本要求の前にOPTIONSを送る条件&quot;">​</a></h2><p>別オリジンへのCORS要求で、たとえば<code>PUT</code>を使う、独自ヘッダーを付ける、<code>POST</code>に<code>Content-Type: application/json</code>を指定する、といった場合は、ブラウザが本要求に先立って<strong>プリフライト</strong>（preflight）の<code>OPTIONS</code>を送ります。その内容を送ってよいか、相手サーバーに確かめるためです。以前に得た許可を専用のプリフライトキャッシュから使えるときは、その通信を省略できます。<a href="https://fetch.spec.whatwg.org/#cors-preflight-fetch" target="_blank" rel="noreferrer">WHATWG FetchのCORS-preflight fetch</a>、<a href="https://fetch.spec.whatwg.org/#cors-preflight-cache" target="_blank" rel="noreferrer">CORS-preflight cache</a></p><p><code>GET</code>、<code>HEAD</code>、<code>POST</code>はCORSの<strong>safelisted method</strong>です。要求ヘッダーについても、名前と値に応じた条件があります。<code>Content-Type</code>の種類では<code>application/x-www-form-urlencoded</code>、<code>multipart/form-data</code>、<code>text/plain</code>が候補です。ほかにプリフライトを要求する条件がなければ、safelistの範囲内の要求は直接送ります。ここで見る<code>Content-Type</code>は要求側のヘッダーです。追加ヘッダーのないGETにサーバーがJSONを返す場合、その応答の<code>Content-Type: application/json</code>でプリフライトが起きることはありません。<a href="https://fetch.spec.whatwg.org/#cors-safelisted-method" target="_blank" rel="noreferrer">WHATWG FetchのCORS-safelisted method</a>、<a href="https://fetch.spec.whatwg.org/#cors-safelisted-request-header" target="_blank" rel="noreferrer">CORS-safelisted request-header</a></p><h3 id="プリフライトと本要求はそれぞれ検査される" tabindex="-1">プリフライトと本要求はそれぞれ検査される <a class="header-anchor" href="#プリフライトと本要求はそれぞれ検査される" aria-label="Permalink to &quot;プリフライトと本要求はそれぞれ検査される&quot;">​</a></h3><p>次は、<code>https://app.example.com</code>から<code>https://api.example.com/score</code>へJSONを<code>PUT</code>する場合のヘッダー例です。要求を始めるJavaScriptは<code>PUT</code>を指定し、プリフライトはブラウザが組み立てます。<a href="https://fetch.spec.whatwg.org/#cors-preflight-fetch" target="_blank" rel="noreferrer">WHATWG FetchのCORS-preflight fetch</a></p><div class="language-http vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">http</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">OPTIONS</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> /score </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">HTTP</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">/</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">1.1</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">Host</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">:</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> api.example.com</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">Origin</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">:</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> https://app.example.com</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">Access-Control-Request-Method</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">:</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> PUT</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">Access-Control-Request-Headers</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">:</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> content-type</span></span></code></pre></div><div class="language-http vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">http</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">HTTP</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">/</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">1.1</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 204</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> No Content</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">Access-Control-Allow-Origin</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">:</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> https://app.example.com</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">Access-Control-Allow-Methods</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">:</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> PUT</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">Access-Control-Allow-Headers</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">:</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> Content-Type</span></span></code></pre></div><p>ブラウザはプリフライト応答のHTTP statusが成功範囲で、必要なオリジン、メソッド、ヘッダーが許可されていることを確かめます。失敗すると本要求を送らず、<code>fetch()</code>が拒否されます。プリフライトを通過すると本要求を送り、その応答でも<code>Access-Control-Allow-Origin</code>などを検査します。ここで失敗した場合、サーバーでは本要求による更新がすでに実行されていても、JavaScriptには応答を渡せません。<a href="https://fetch.spec.whatwg.org/#cors-preflight-fetch" target="_blank" rel="noreferrer">WHATWG FetchのCORS-preflight fetch</a>、<a href="https://fetch.spec.whatwg.org/#cors-check" target="_blank" rel="noreferrer">CORS check</a></p><figure class="study-figure"><img src="`+c+'" alt="別オリジンへのCORS取得では、必要な場合にOPTIONSで先に許可を検査する。そこで失敗すると本要求を送らない。通過した場合とプリフライト不要の場合は本要求へ進み、受け取った応答のCORS条件を検査することを示す図" width="760" height="1200" loading="lazy"><figcaption>拒否が起きた時点で、本要求が送られているかが変わります。プリフライトの許可を専用キャッシュから再利用できる場合もあります。<a href="/study/images/browser/cors-preflight.svg" target="_blank" rel="noopener">図を拡大する</a></figcaption></figure><h2 id="javascriptから見えるresponse" tabindex="-1">JavaScriptから見えるResponse <a class="header-anchor" href="#javascriptから見えるresponse" aria-label="Permalink to &quot;JavaScriptから見えるResponse&quot;">​</a></h2><table tabindex="0"><thead><tr><th>取得経路</th><th>代表的な結果</th><th>JavaScriptから見える内容</th></tr></thead><tbody><tr><td>同一オリジンへの通常の取得</td><td><code>type: &quot;basic&quot;</code></td><td>status、本文、公開可能な応答ヘッダー</td></tr><tr><td>別オリジンでCORS検査を通過</td><td><code>type: &quot;cors&quot;</code></td><td>status、本文、safelistや<code>Access-Control-Expose-Headers</code>に従う応答ヘッダー</td></tr><tr><td>別オリジンへの<code>no-cors</code>取得でopaque応答を受領</td><td><code>type: &quot;opaque&quot;</code></td><td><code>status: 0</code>、<code>ok: false</code>、空のヘッダー、本文の公開なし</td></tr><tr><td>CORS検査の失敗や通信エラー</td><td><code>fetch()</code>が拒否</td><td>検査できるHTTP応答は渡されない</td></tr></tbody></table><p><code>mode: &quot;no-cors&quot;</code>では、指定できる要求メソッドやヘッダーが限られ、別オリジンの応答を読める範囲も狭くなります。opaque応答の0は、実際に受信したHTTP statusを伏せた値です。取得先や応答の種類、ブラウザのポリシーによっては<code>no-cors</code>取得自体が失敗することもあります。取得したデータをJavaScriptで処理する用途では、CORSで公開条件を整えます。<a href="https://fetch.spec.whatwg.org/#concept-request-mode" target="_blank" rel="noreferrer">WHATWG Fetchの要求モード</a>、<a href="https://fetch.spec.whatwg.org/#concept-filtered-response" target="_blank" rel="noreferrer">filtered response</a></p><p>CORS検査を通過した<code>404</code>や<code>500</code>の本応答は、HTTP statusを持つ<code>Response</code>として扱えます。一方、CORSによる失敗はJavaScriptからは通信エラーに近い形で見えます。DevToolsのConsoleで失敗の理由を確認し、Networkで<code>OPTIONS</code>と本要求を分けて、status・要求側の<code>Origin</code>・応答側の<code>Access-Control-Allow-*</code>を照合します。配信側のログがあれば、どの要求が届いたかも確認できます。<a href="https://fetch.spec.whatwg.org/#fetch-method" target="_blank" rel="noreferrer">WHATWG Fetchのfetchメソッド</a>、<a href="https://developer.chrome.com/docs/devtools/network/reference/" target="_blank" rel="noreferrer">Chrome DevToolsのNetworkリファレンス</a></p><h2 id="資格情報と公開する相手" tabindex="-1">資格情報と公開する相手 <a class="header-anchor" href="#資格情報と公開する相手" aria-label="Permalink to &quot;資格情報と公開する相手&quot;">​</a></h2><p><code>fetch()</code>の<code>credentials</code>は、CookieやHTTP認証などの資格情報を取得で使うかを指定します。既定の<code>same-origin</code>では同一オリジンに限って使い、<code>omit</code>では使いません。別オリジンへの<code>include</code>では資格情報の利用を要求しますが、実際に送られるCookieは<code>SameSite</code>やブラウザのCookie制限にも従います。<a href="https://fetch.spec.whatwg.org/#concept-request-credentials-mode" target="_blank" rel="noreferrer">WHATWG Fetchのcredentials mode</a>、<a href="https://fetch.spec.whatwg.org/#cors-protocol-and-credentials" target="_blank" rel="noreferrer">CORS protocol and credentials</a></p><table tabindex="0"><thead><tr><th>条件</th><th>公開を許可する応答ヘッダーの例</th></tr></thead><tbody><tr><td>誰でも読める公開ファイルを<code>credentials: &quot;omit&quot;</code>で取得</td><td><code>Access-Control-Allow-Origin: *</code></td></tr><tr><td><code>https://app.example.com</code>から<code>credentials: &quot;include&quot;</code>で取得</td><td><code>Access-Control-Allow-Origin: https://app.example.com</code> と <code>Access-Control-Allow-Credentials: true</code></td></tr></tbody></table><p><code>include</code>では、実際にCookieが送られたかにかかわらず、<code>Access-Control-Allow-Origin: *</code>は検査を通過しません。プリフライトのOPTIONSには資格情報が付きませんが、資格情報付きの本要求を許可するには、その許可をプリフライト応答にも示します。<code>Authorization</code>のような要求ヘッダーは、必要なときに<code>Access-Control-Allow-Headers</code>へ名前を明示します。独自の<strong>応答</strong>ヘッダーをJavaScriptに公開する指定は<code>Access-Control-Expose-Headers</code>です。<a href="https://fetch.spec.whatwg.org/#cors-protocol-and-credentials" target="_blank" rel="noreferrer">WHATWG FetchのCORS protocol and credentials</a>、<a href="https://fetch.spec.whatwg.org/#cors-preflight-fetch" target="_blank" rel="noreferrer">CORS-preflight fetch</a></p><p>複数のオリジンを許可する構成では、要求の<code>Origin</code>を許可リストと照合し、一致した値を<code>Access-Control-Allow-Origin</code>に返します。応答が<code>Origin</code>によって変わる場合は<code>Vary: Origin</code>を指定し、HTTPキャッシュが別のオリジン用の応答を使い回すことを防ぎます。プリフライトの許可を再利用する時間は、別に<code>Access-Control-Max-Age</code>で指定できます。<a href="https://fetch.spec.whatwg.org/#cors-protocol-and-http-caches" target="_blank" rel="noreferrer">WHATWG FetchのCORS protocol and HTTP caches</a>、<a href="/study/network/http-caching.html">HTTPキャッシュ</a></p><p>要求にCookieが付く条件と、受け取ったIDをサーバーがどう照合するかは、<a href="/study/browser/cookies-and-sessions.html">Cookieとセッション</a>で扱います。</p><p>ページが別オリジンの画像などを埋め込む条件には、COEPやCORPも関わります。CORSとどこで判断が分かれるかは、<a href="/study/browser/cross-origin-isolation.html">クロスオリジン分離と共有メモリ</a>で扱います。</p><h2 id="更新を許可する判断はサーバーで行う" tabindex="-1">更新を許可する判断はサーバーで行う <a class="header-anchor" href="#更新を許可する判断はサーバーで行う" aria-label="Permalink to &quot;更新を許可する判断はサーバーで行う&quot;">​</a></h2><p>サーバーには、利用者の認証、その操作を行う権限の確認、必要に応じた<strong>CSRF</strong>（利用者のセッションを使った意図しない送信）への対策が必要です。たとえば状態を変更するフォームが別サイトから送信され、条件次第でCookieが付くことがあります。応答の読み取りが制限されても更新は起き得るため、サーバーがCSRFトークンの照合などで要求を検査します。<a href="https://cheatsheetseries.owasp.org/cheatsheets/Cross-Site_Request_Forgery_Prevention_Cheat_Sheet.html" target="_blank" rel="noreferrer">OWASPのCSRF対策</a></p><p><a href="/study/browser/service-worker-offline.html">Service Workerとオフライン動作</a>では、制御中のページが行った取得に対し、ワーカーが保存済み応答を選ぶ場面を扱いました。ワーカー自身が別オリジンへ<code>fetch()</code>するときも、要求モードとCORS検査に従います。別オリジンのopaque応答をCache APIへ保存して取り出しても、JavaScriptから見える部分は変わりません。<a href="https://fetch.spec.whatwg.org/#main-fetch" target="_blank" rel="noreferrer">WHATWG FetchのMain fetch</a>、<a href="https://w3c.github.io/ServiceWorker/#cache-interface" target="_blank" rel="noreferrer">Service WorkersのCache</a></p><h2 id="実践との対応" tabindex="-1">実践との対応 <a class="header-anchor" href="#実践との対応" aria-label="Permalink to &quot;実践との対応&quot;">​</a></h2><p>実践では、通常のページと不透明なオリジンを持つ<code>iframe</code>から、同じ固定ファイルを要求します。要求モードと独自ヘッダーの有無を切り替え、画面の<code>Response.type</code>、status、本文の公開状態を見比べます。DevToolsやローカル配信のログを併用すると、プリフライトと本要求のどちらが届いたかまで確かめられます。<a href="/study/practice/browser/cors-observation.html">同一オリジンとCORSの応答を観察する</a></p>',36)])])}const m=t(i,[["render",h]]);export{k as __pageData,m as default};
